import type { RetryPolicy } from './types.js'

/**
 * Shared retry policy for every consumer.
 * attempt 1 fails -> wait 1s, attempt 2 fails -> wait 2s, attempt 3 fails -> wait 4s,
 * then the message goes to the dead-letter queue.
 */
export const retryPolicy: RetryPolicy = {
  maxRetries: 3,
  backoff: { type: 'exponential', initialDelayMs: 1_000, factor: 2 },
}

export function delayFor(attempt: number): number {
  const { initialDelayMs, factor } = retryPolicy.backoff
  return initialDelayMs * factor ** (attempt - 1)
}

