import { writeFile } from 'node:fs/promises'
import type { Command } from 'commander'
import { apiClient, type Invoice } from '../../api.js'
import { UsageError } from '../../errors.js'

const FORMATS = ['csv', 'json'] as const
type Format = (typeof FORMATS)[number]

export function toCsv(rows: Invoice[]): string {
  const header = 'number,client,status,total_cents,due_date'
  const lines = rows.map((r) =>
    [r.number, JSON.stringify(r.client), r.status, r.totalCents, r.dueDate].join(','),
  )
  return [header, ...lines].join('\n') + '\n'
}

export function registerInvoicesExport(invoices: Command) {
  invoices
    .command('export')
    .description('Export invoices to a file')
    .option('--format <format>', 'csv or json', 'csv')
    .option('--status <status>', 'filter by status')
    .requiredOption('--out <file>', 'output path')
    .action(async (opts: { format: string; status?: string; out: string }) => {
      if (!FORMATS.includes(opts.format as Format)) {
        throw new UsageError(`--format must be one of ${FORMATS.join(', ')}`)
      }
      const rows = await apiClient.listInvoices({ status: opts.status, limit: 'all' })
      const body = opts.format === 'csv' ? toCsv(rows) : JSON.stringify(rows, null, 2) + '\n'
      await writeFile(opts.out, body)
      console.log(`Wrote ${rows.length} invoices to ${opts.out}`)
    })
}

