const DAY_MS = 86_400_000

function startOfDayUtc(d: Date): number {
  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())
}

/** 'due today', 'due tomorrow', 'due in 3 days', 'overdue by 1 day', 'overdue by 2 days'. */
export function dueLabel(dueDate: string, now: Date = new Date()): string {
  const days = Math.round((startOfDayUtc(new Date(dueDate)) - startOfDayUtc(now)) / DAY_MS)
  if (days === 0) return 'due today'
  if (days === 1) return 'due tomorrow'
  if (days > 1) return `due in ${days} days`
  const late = -days
  return `overdue by ${late} ${late === 1 ? 'day' : 'days'}`
}

