import { and, desc, eq } from 'drizzle-orm'
import { db } from '../../db/client.js'
import { orders, orderItems, clients } from '../../db/schema/index.js'
import { ListOrdersQuery } from './schemas.js'

export default async function listOrders(app: FastifyInstance) {
  app.get('/v1/orders', async (request) => {
    const { limit, cursor } = ListOrdersQuery.parse(request.query)
    const orgId = request.auth.orgId

    const rows = await db
      .select()
      .from(orders)
      .where(eq(orders.orgId, orgId))
      .orderBy(desc(orders.createdAt))
      .limit(limit)

    const result = []
    for (const order of rows) {
      const items = await db.select().from(orderItems)
        .where(and(eq(orderItems.orderId, order.id), eq(orderItems.orgId, orgId)))
      const [client] = await db.select().from(clients)
        .where(and(eq(clients.id, order.clientId), eq(clients.orgId, orgId)))
      result.push({ ...order, items, client })
    }
    return { data: result, nextCursor: rows.at(-1)?.id ?? null }
  })
}

