#!/usr/bin/env tsx
/**
 * List remote branches whose last commit is older than N days (default 60).
 * Read-only: prints a table, never deletes anything.
 *   pnpm tsx scripts/stale-branches.ts [--days 60] [--remote origin]
 */
import { execFileSync } from 'node:child_process'
import { parseArgs } from 'node:util'

const { values } = parseArgs({
  options: {
    days: { type: 'string', default: '60' },
    remote: { type: 'string', default: 'origin' },
  },
})

const days = Number(values.days)
const remote = values.remote ?? 'origin'
const cutoff = Date.now() - days * 86_400_000

execFileSync('git', ['fetch', remote, '--prune', '--quiet'])
const out = execFileSync(
  'git',
  ['for-each-ref', `refs/remotes/${remote}`, '--format=%(refname:short)\t%(committerdate:iso-strict)\t%(authorname)'],
  { encoding: 'utf8' },
)

const stale = out
  .trim()
  .split('\n')
  .map((line) => line.split('\t'))
  .filter(([name]) => name && !name.endsWith('/HEAD') && name !== `${remote}/main`)
  .map(([name = '', date = '', author = '']) => ({ name, date, author, ts: Date.parse(date) }))
  .filter((b) => b.ts < cutoff)
  .sort((a, b) => a.ts - b.ts)

for (const b of stale) {
  const age = Math.floor((Date.now() - b.ts) / 86_400_000)
  console.log(`${b.name.padEnd(48)} ${b.date.slice(0, 10)}  ${String(age).padStart(4)}d  ${b.author}`)
}
console.log(`\n${stale.length} branches older than ${days} days on ${remote}`)

